pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount < type(uint256).max);
        vm.prank(address(this));
        try c.AdjustDifficulty(amount) {
            assertEq(c.currentDifficulty(), amount);
        } catch {
            assertTrue(false, "AdjustDifficulty should not revert");
        }
    }
}
